    // @item fn:tuas_boussinesq_solver::boussinesq_thermophysical_properties::liquid_database::hitec_nitrate_salt::get_hitec_dynamic_viscosity
#[doc = "function to obtain nitrate salt viscosity\ngiven a temperature\n\nDu, B. C., He, Y. L., Qiu, Y., Liang, Q., & Zhou, Y. P. (2018).\nInvestigation on heat transfer characteristics of molten salt in\na shell-and-tube heat exchanger. International Communications\nin Heat and Mass Transfer, 96, 61-68.\n\nmu Pa-s (T = 440 - 500 K)\n= 0.93845\n-0.54754 T(K)\n+ 1.08225e-5 T(K)^2\n- 7.2058e-9 T(K)^3\n\nmu Pa-s (T = 500 - 800 K)\n= 0.23816\n- 1.2768e-3 T(K)\n+ 2.6275e-6 T(K)^2\n- 2.4331e-9 T(K)^3\n+ 8.507e-13 T(K)^4\n\nBohlmann, E. G. (1972). HEAT TRANSFER SALT FOR HIGH TEMPERATURE\nSTEAM GENERATION (No. ORNL-TM-3777). Oak Ridge National\nLab.(ORNL), Oak Ridge, TN (United States).\n\ngiven the complicated looking correlations, it's always good to\nagainst data. I'm using Bohlman's data for HITEC salt in 1972\nas comparison. Fig 6 on page 25 of the document shows a graph\nof HITEC salt viscosity in centipoises against temperature in\nFahrenheit\n\nUsing graphreader, I got the following pieces of data for viscosity\nin cP against temp in Fahrenheit (roughly, the curve axes were\ntilted)\n\n\n315.282,15.039\n336.479,12.087\n346.338,10.984\n375.915,8.642\n399.577,7.362\n440.986,5.709\n498.169,4.272\n585.915,3.051\n653.944,2.5\n730.845,1.98"]
#[pyfunction(name = "get_hitec_dynamic_viscosity")]
pub fn fn_tuas_boussinesq_solver__boussinesq_thermophysical_properties__liquid_database__hitec_nitrate_salt__get_hitec_dynamic_viscosity(fluid_temp: f64) -> PyResult<f64> { err(::tuas_boussinesq_solver::boussinesq_thermophysical_properties::liquid_database::hitec_nitrate_salt::get_hitec_dynamic_viscosity(from_si(fluid_temp))).map(|v| to_si(v)) }

    // @item fn:tuas_boussinesq_solver::boussinesq_thermophysical_properties::liquid_database::hitec_nitrate_salt::get_hitec_specific_enthalpy
#[doc = "function to obtain nitrate salt specific enthalpy\ngiven a temperature\nDu, B. C., He, Y. L., Qiu, Y., Liang, Q., & Zhou, Y. P. (2018).\nInvestigation on heat transfer characteristics of molten salt in\na shell-and-tube heat exchanger. International Communications\nin Heat and Mass Transfer, 96, 61-68.\n\ncp (J/kg/K) = 1560.0\nT in kelvin\n\nManual integration with temperature yields:\n\nh (J/kg) = 1560.0 T(K) + Constant\n\nI can just adjust the enthalpy to be 0 J/kg at 440K\n\n0 J/kg = 1560 * T_0 (K) + Constant\nConstant = 0 - 1560 T_0 (K)\nConstant = 0 - 1560 * 440\nConstant = 0 - 686,400\n\nh (J/kg) = 1560.0 T(K) - 686400\nh (J/kg) = - 686400 + 1560.0 T(K)\n\n\n"]
#[pyfunction(name = "get_hitec_specific_enthalpy")]
pub fn fn_tuas_boussinesq_solver__boussinesq_thermophysical_properties__liquid_database__hitec_nitrate_salt__get_hitec_specific_enthalpy(fluid_temp: f64) -> PyResult<f64> { err(::tuas_boussinesq_solver::boussinesq_thermophysical_properties::liquid_database::hitec_nitrate_salt::get_hitec_specific_enthalpy(from_si(fluid_temp))).map(|v| to_si(v)) }

    // @item fn:tuas_boussinesq_solver::boussinesq_thermophysical_properties::liquid_database::hitec_nitrate_salt::get_hitec_thermal_conductivity
#[doc = "function to obtain nitrate salt thermal conductivity\ngiven a temperature\n\nDu, B. C., He, Y. L., Qiu, Y., Liang, Q., & Zhou, Y. P. (2018).\nInvestigation on heat transfer characteristics of molten salt in\na shell-and-tube heat exchanger. International Communications\nin Heat and Mass Transfer, 96, 61-68.\n\nk (thermal conductivity in W/mK for T = 536-800 kelvin) =\n0.7663 - 6.47e-4 T(K)\n\nk (thermal conductivity in W/mK for T = 420-536 kelvin) =\n2.2627 - 0.01176 T(K)\n+ 2.551e-5 T(K)^2\n- 1.863e-8 T(K)^3\n\nT in kelvin"]
#[pyfunction(name = "get_hitec_thermal_conductivity")]
