    // @item fn:tuas_boussinesq_solver::fluid_mechanics_correlations::courant_number::courant_number_3d_openfoam_algorithm_velocity
#[doc = "courant number 3D\n\ncalculates the CFL number for a 3D case\n\nthis is based on OpenFOAM's Courant number algorithm:\n\nCo =  0.5 * timestep / volume *  \n(summation (dot product of U and Area).abs())\n\nCo =  0.5 * timestep / volume *  \n(summation (dot product of U and normal vector).abs()*Area_magnitude)\n\nthis takes in three vectors, the volume of the control volume\nand a timestep\n\nThis is for an arbitrarily shaped control volume with a number\nof flat faces\n\nthe first vector specifies fluid velocity at each of these flat\nfaces\n\nthe second vector specifies the angle to the normal that these\nvelocities make with the area normals\nwe can define area normals as pointing inwards towards the\ncenter of the cell,\n\nbut it doesn't really matter, we need to take the absolute value of\nthe dot product of the velocities with the normals anyhow\n"]
#[pyfunction(name = "courant_number_3d_openfoam_algorithm_velocity")]
pub fn fn_tuas_boussinesq_solver__fluid_mechanics_correlations__courant_number__courant_number_3d_openfoam_algorithm_velocity(control_volume_volume: f64, timestep: f64, face_area_vector: Vec<f64>, velocity_vector: Vec<f64>, angle_between_area_normals_and_velocity_vector: Vec<f64>) -> PyResult<f64> { err(::tuas_boussinesq_solver::fluid_mechanics_correlations::courant_number::courant_number_3d_openfoam_algorithm_velocity(from_si(control_volume_volume), from_si(timestep), face_area_vector.into_iter().map(|e| from_si(e)).collect::<Vec<_>>(), velocity_vector.into_iter().map(|e| from_si(e)).collect::<Vec<_>>(), angle_between_area_normals_and_velocity_vector.into_iter().map(|e| from_si(e)).collect::<Vec<_>>())).map(|v| v) }

