    // @item fn:tuas_boussinesq_solver::fluid_mechanics_correlations::get_bejan_d
#[doc = "This function calculates the bejan number\n\nthis is the\n\n\nBe = (P * D^2)/(mu * nu)\n\nP is pressure loss\nD is hydraulic diameter\nmu is dynamic viscosity\nnu is kinematic viscosity\n\nBe is the bejan number which is dimensionless\n\nIt is calculated using:\nBe = 0.5 * Re^2 * (f * (L/D) + K)\n\nthe f is darcy friction factor\n\nand the term in the brackets is fldk\n\nyou are to give a K value, L/D value, Re\nand roughness ratio\n\nRe = 0  and Re < 0 is supported,\nthis assumes that the component is symmetrical\nin terms of pressure loss, which may usually\nbe the case for pipes anyhow\n\n\n\n```rust\nlet bejan_d =\n    tuas_boussinesq_solver::\n    fluid_mechanics_correlations::get_bejan_d(\n        0.00000000000001,0.00014,10.0,5.0).unwrap();\n\nprintln!(\"{}\", bejan_d);\n\nlet bejan_d =\n    tuas_boussinesq_solver::\n    fluid_mechanics_correlations::get_bejan_d(\n        -5000.0,0.00014,10.0,5.0).unwrap();\n\nprintln!(\"{}\", bejan_d);\n\nlet bejan_d =\n    tuas_boussinesq_solver::\n    fluid_mechanics_correlations::get_bejan_d(\n        0.0,0.00014,10.0,5.0).unwrap();\n\nprintln!(\"{}\", bejan_d);\n```"]
#[pyfunction(name = "get_bejan_d")]
pub fn fn_tuas_boussinesq_solver__fluid_mechanics_correlations__get_bejan_d(reynolds_number: f64, roughness_ratio: f64, length_to_diameter_ratio: f64, k: f64) -> PyResult<f64> { err(::tuas_boussinesq_solver::fluid_mechanics_correlations::get_bejan_d(reynolds_number, roughness_ratio, length_to_diameter_ratio, k)).map(|v| v) }

    // @item fn:tuas_boussinesq_solver::fluid_mechanics_correlations::get_reynolds_number
#[doc = "This function calculates the Reynolds number given\na Bejan number.\n\nRemember Bejan number is dimensionless pressure\ndrop\n\nBe = (P * D^2)/(mu * nu)\n\nP is pressure loss\nD is hydraulic diameter\nmu is dynamic viscosity\nnu is kinematic viscosity\n\nWe implicitly solve for Re using:\nBe = 0.5 * Re^2 * (f * (L/D) + K)\n\nthe f is darcy friction factor\n\nand the term in the brackets is fldk\n\nyou are to give a K value, L/D value, Be\nand roughness ratio\n\nRe = 0  and Re < 0 is supported,\nthis assumes that the component is symmetrical\nin terms of pressure loss, which may usually\nbe the case for pipes anyhow\n\n\nIn the following example, we get a bejan number calculated\nfirst with Re = 5000.0\nand then using that bejan number, we try and find the Re again\nwhich should be about 5000.0\n\nwe use the approx package and ensure that the numbers are similar\nto within 0.001 or 0.1% of each other\n\n```rust\n\nextern crate approx;\nlet bejan_d =\ntuas_boussinesq_solver::fluid_mechanics_correlations::\n    get_bejan_d(\n        5000.0,0.00014,10.0,5.0).unwrap();\n\nprintln!(\"{}\", bejan_d);\n\nlet reynolds_number =\ntuas_boussinesq_solver::fluid_mechanics_correlations::\n    get_reynolds_number(\n        bejan_d,0.00014,10.0,5.0)"]
#[pyfunction(name = "get_reynolds_number")]
pub fn fn_tuas_boussinesq_solver__fluid_mechanics_correlations__get_reynolds_number(bejan_d: f64, roughness_ratio: f64, length_to_diameter: f64, form_loss_k: f64) -> PyResult<f64> { err(::tuas_boussinesq_solver::fluid_mechanics_correlations::get_reynolds_number(bejan_d, roughness_ratio, length_to_diameter, form_loss_k)).map(|v| v) }

