pub fn fn_tuas_boussinesq_solver__heat_transfer_correlations__nusselt_number_correlations__pipe_correlations__gnielinski_correlation_liquids_fully_developed(reynolds_number: f64, prandtl_number_bulk_fluid: f64, prandtl_number_wall: f64, darcy_friction_factor: f64) -> f64 { ::tuas_boussinesq_solver::heat_transfer_correlations::nusselt_number_correlations::pipe_correlations::gnielinski_correlation_liquids_fully_developed(reynolds_number, prandtl_number_bulk_fluid, prandtl_number_wall, darcy_friction_factor) }

    // @item fn:tuas_boussinesq_solver::heat_transfer_correlations::nusselt_number_correlations::pipe_correlations::gnielinski_turbulent_correlation_liquids_developing
#[doc = "estimates Nusselt Number for thermally developing flow\nin turbulent regime (Re > 4000)\nfor tubes\nregardless of boundary conditions\nregardless of boundary conditions (constant heat flux, wall temp\nmixed or anything else)\n\n\nRe, Pr_fluid is measured at film temp\nT_film = (T_bulk + T_wall)/2\n\nWhere:\nT_bulk = (T_in + T_out)/2\n\nFor the correction factor,\n\n(Pr_bulk/Pr_wall) is used.\n\nYou may choose to set Pr_bulk = Pr_film if you so wish, but there\nis flexibility in this aspect\n"]
