    // @item fn:tuas_boussinesq_solver::heat_transfer_correlations::view_factors::cocentric_cylinders::outer_cylinder_self_view_factor
#[doc = "F_(2-2) =  1 - 1/R - ((H^2 + 4 R^2)^0.5 -H)/(4 R) + 1/PI * B\n\n\nWhere B = 2/R atan (2 * sqrt(R^2 - 1)/H) - H/(2 R) * C\n\nAnd C = D asin(E) - asin (F)\n\nD = sqrt(4 R^2 + H^2)/H\nE = (H^2 + 4(R^2 - 1) - 2 H^2/R^2)/(H^2  + 4 (R^2 - 1))\n\nF = (R^2 - 2)/R^2\n\nformula inspected ok 8:34pm 06 nov"]
#[pyfunction(name = "outer_cylinder_self_view_factor")]
pub fn fn_tuas_boussinesq_solver__heat_transfer_correlations__view_factors__cocentric_cylinders__outer_cylinder_self_view_factor(inner_diameter: f64, outer_diameter: f64, cylinder_height: f64) -> f64 { to_si(::tuas_boussinesq_solver::heat_transfer_correlations::view_factors::cocentric_cylinders::outer_cylinder_self_view_factor(from_si(inner_diameter), from_si(outer_diameter), from_si(cylinder_height))) }

    // @item fn:tuas_boussinesq_solver::heat_transfer_correlations::view_factors::cocentric_cylinders::outer_cylinder_to_annular_end_ring_view_factor
#[doc = "outer cylinder to annular end ring (enclosing space between\ncoaxial cylinders)\n\n\nterms:\nr_1 = inner_radius\nr_2 = outer_radius\n\nH = cylinder_height/r_2\nR = r_1/r_2\n\nX = sqrt(1-R^2)\nY = (R(1 - R^2 - H^2))/(1 - R^2 + H^2)\n\nF_(1-2) = 1/PI * (A + B + C - D + E)\n\n\nA =  R (atan(X/H) -  atan(2X/H))\n\nB = H/4 * ( asin(2R^2 - 1) - asin (R))\n\nC = X^2/(4 H) * (PI/2 + asin(R))\n\nD = d1 * d2\n\nd1 = sqrt( (1 + R^2 + H^2)^2 -  4 R^2) / (4H)\nd2 = PI/2 + asin(Y)\n\nE = e1 * e2\n\ne1 = sqrt (4 + H^2)/4\ne2 = PI/2 + asin(1 -  2 R^2 H^2 / (4 X^2 + H^2))"]
#[pyfunction(name = "outer_cylinder_to_annular_end_ring_view_factor")]
pub fn fn_tuas_boussinesq_solver__heat_transfer_correlations__view_factors__cocentric_cylinders__outer_cylinder_to_annular_end_ring_view_factor(inner_diameter: f64, outer_diameter: f64, cylinder_height: f64) -> f64 { to_si(::tuas_boussinesq_solver::heat_transfer_correlations::view_factors::cocentric_cylinders::outer_cylinder_to_annular_end_ring_view_factor(from_si(inner_diameter), from_si(outer_diameter), from_si(cylinder_height))) }

    // @item fn:tuas_boussinesq_solver::heat_transfer_correlations::view_factors::cocentric_cylinders::outer_cylinder_to_inner_cylinder_view_factor
#[doc = "F_(2-1) = 1/R * ( 1 - B - 1/PI C )\n\nC = D - E - F\n\nD = acos (hsq_minus_rsq_plus_one/hsq_plus_rsq_minus_one)\nE = e1 acos (e2)\n\ne1 = sqrt( hsq_plus_rsq_plus_one^2 - 4.0 * rsq)/(2H)\ne2 = (hsq_minus_rsq_plus_one)/(R * hsq_plus_rsq_minus_one)\n\n\nhsq_minus_rsq_plus_one = H^2 - R^2 + 1\nhsq_plus_rsq_minus_one = H^2 + R^2 - 1\nhsq_plus_rsq_plus_one = H^2 + R^2 + 1\n\nF = (hsq_minus_rsq_plus_one)/(2H) asin (1/R)\n\nB = (hsq_plus_rsq_minus_one)/(4 H)\n\n\nouter cylinder to inner cylinder view factor\n\nvisually inspected 8:39pm 06 nov 2024"]
#[pyfunction(name = "outer_cylinder_to_inner_cylinder_view_factor")]
pub fn fn_tuas_boussinesq_solver__heat_transfer_correlations__view_factors__cocentric_cylinders__outer_cylinder_to_inner_cylinder_view_factor(inner_diameter: f64, outer_diameter: f64, cylinder_height: f64) -> f64 { to_si(::tuas_boussinesq_solver::heat_transfer_correlations::view_factors::cocentric_cylinders::outer_cylinder_to_inner_cylinder_view_factor(from_si(inner_diameter), from_si(outer_diameter), from_si(cylinder_height))) }

